const parseDeliveries = value => {
  const map = JSON.parse(value || "{}");
  if (!map || Array.isArray(map) || typeof map !== "object" || !Object.keys(map).length ||
      Object.entries(map).some(([id,msg]) => !/^\d+$/.test(id) || id === "0" || (msg !== null && (typeof msg !== "string" || !msg)))) {
    throw new Error("Invalid deliveries_json");
  }
  return map;
};
const escape = value => String(value ?? "")
  .replace(/&/g, "&amp;")
  .replace(/</g, "&lt;")
  .replace(/>/g, "&gt;");

const price = value => Number.isFinite(value)
  ? `${value.toFixed(2)} PLN`
  : "no data";

const CONDITIONS = {
  "Nowy z metką": ["🏷️", "New with tags"],
  "Nowy bez metki": ["✨", "New without tags"],
  "Bardzo dobry": ["🟢", "Very good"],
  "Dobry": ["🟡", "Good"],
  "Zadowalający": ["🟠", "Satisfactory"]
};

return $input.all().flatMap((item, index) => {
  const row = item.json;
  const p = JSON.parse(row.payload_json);
  // Values are escaped; only the fixed <b> tags are Telegram HTML.
  const searchId = escape(String(row.search_id || p.search_id || "").slice(0, 64));
  const searchName = escape(String(p.search_name || row.search_name || "").slice(0, 180));
  const field = (label, value) => `<b>${label}:</b> ${escape(value)}`;

  // Marketplace puts the model into the brand text: "JBL, Model: Tune 720BT".
  const [brand, model] = String(p.brand || "").split(/,\s*Model:\s*/);
  const conditionRaw = String(p.condition || "").trim();
  const condition = CONDITIONS[conditionRaw] || ["❔", conditionRaw || "—"];

  const caption = [
    `<b>${escape(String(p.title || "").slice(0, 200))}</b>`,
    "",
    "💰 " + field("Price", price(p.price)),
    "➕ " + field("With fee", `${price(p.total)} (without delivery)`),
    condition[0] + " " + field("State", condition[1].slice(0, 80)),
    field("Size", String(p.size || "—").slice(0, 40)),
    field("Brand", String(brand || "—").slice(0, 80)),
    ...(model ? [field("Model", model.slice(0, 80))] : []),
    "",
    "🔎 <b>Search:</b> " + (searchName ? `${searchName} (ID: ${searchId})` : `ID: ${searchId}`),
    "🆔 " + field("ID item on the marketplace", String(p.id || row.item_id || "—").slice(0, 40))
  ].join("\n");

  const deliveries=parseDeliveries(row.deliveries_json);
  const targets=Object.keys(deliveries).filter(id=>deliveries[id] === null);
  // The last successful checkpoint normally closes the row immediately.
  // A no-op item also repairs manually imported pending rows already delivered.
  return (targets.length ? targets : [null]).map(chatId=>({
    json:{...row,photo:p.photo,url:p.url,caption,chat_id:chatId,skip_delivery:chatId === null},
    pairedItem:{item:index}
  }));
});

const target=$("Card recipients").item.json;
const input=$input.first().json;
const messageId=input.message_id ?? input.result?.message_id;
const success=(typeof messageId === "number" && Number.isFinite(messageId) && messageId > 0) || (typeof messageId === "string" && /^\d+$/.test(messageId) && messageId !== "0");
const error=input.error ?? input;
const message=typeof error === "string" ? error : String(error.message ?? input.message ?? "Telegram did not confirm sending");
const retryAfter=Number(error?.parameters?.retry_after ?? input.parameters?.retry_after ?? message.match(/retry after (\d+)/i)?.[1] ?? 0);
return [{json:{queue_id:target.id,item_id:target.item_id,
  target_chat_id:target.chat_id,deliveries_json:target.deliveries_json,
  search_id:target.search_id,delivery_success:success,
  telegram_result_id:success ? String(messageId) : null,
  recipient_error:success ? "" : (target.chat_id+": "+message).slice(0,1000),
  retry_after:Number.isFinite(retryAfter) ? retryAfter : 0}}];

const rh=(function createPolicy() {
  const fail=m=>{throw Error('Independent searches: '+m);};
  const validId=n=>Number.isSafeInteger(n)&&n>0;
  const validItem=s=>typeof s==='string'&&/^[1-9][0-9]*$/.test(s);
  function owner(r){
    if(!r||typeof r.search_id!=='string'||!r.search_id.trim())fail('no unambiguous owner');
    return r.search_id;
  }
  function key(r){owner(r);if(!validItem(r.item_id))fail('invalid item_id');return JSON.stringify([r.search_id,r.item_id]);}
  function rows(items){return items.map(i=>{
    if(i.error||!i.json&&typeof i!=='object')fail('read error');
    const r=i.json??i;if(!r||r.error||r._rh_io||r._baseline_io)fail('read not confirmed');return r;
  }).filter(r=>{if(!Object.keys(r).length)return false;if(!validId(r.id))fail('no system id');return true;});}
  function deliveries(r){let d;try{d=JSON.parse(r.deliveries_json);}catch{fail('deliveries corrupted');}
    if(!d||Array.isArray(d)||typeof d!=='object'||!Object.keys(d).length||Object.entries(d).some(([id,msg])=>!validItem(id)||msg!==null&&!validItem(msg)))fail('deliveries corrupted');return d;
  }
  function distinct(data){const keys=new Set(),ids=new Set();for(const r of data){const k=key(r);if(!validId(r.id)||keys.has(k)||ids.has(r.id))fail('corrupted rows or duplicates of one task');keys.add(k);ids.add(r.id);}return data;}
  function notifications(data){distinct(data);for(const r of data){if(!['pending','sent','failed','cancelled'].includes(r.status))fail('unknown status');const d=deliveries(r);if(r.status==='sent'&&Object.values(d).some(x=>x===null))fail('incomplete sent');}return data;}
  function validatePayload(r){
    key(r);let p;try{p=JSON.parse(r.payload_json);}catch{fail('item data corrupted');}
    if(!p||Array.isArray(p)||typeof p!=='object'||key(p)!==key(r)||typeof p.url!=='string'||!/^https:\/\/(?:www\.)?marketplace\.example\/items\/[1-9][0-9]*(?:[-/?#]|$)/i.test(p.url))fail('item data does not match the owner');
    const urlItem=p.url.match(/\/items\/([1-9][0-9]*)/i)[1];if(urlItem!==r.item_id)fail('URL of another item');return p;
  }
  function current(r,searches){
    key(r);if(searches.some(s=>s.search_id!==r.search_id)||searches.length>1)fail('ambiguous search');
    const p=validatePayload(r),s=searches[0],ok=!!s&&typeof s.url==='string'&&!!s.url&&s.url===s.applied_url&&p.source_url===s.url;
    return {...r,search_name:ok?String(s.name||r.search_id):'',delivery_allowed:ok,cancel_reason:ok?'':'Search deleted or its conditions changed'};
  }
  return {current,rows,fail,validId,key,validatePayload,validItem,owner,notifications,deliveries,distinct};
})();
const row=$('Take notification').all(0,-1)[0].json;return [{json:rh.current(row,rh.rows($input.all()))}];

