const row=$input.first().json;
const result=$("Send result").item.json;
if(row.id!==result.queue_id||row.search_id!==result.search_id||row.item_id!==result.item_id)throw Error('Another task during delivery confirmation');
const deliveries=parseDeliveries(row.deliveries_json);
if (!Object.hasOwn(deliveries,result.target_chat_id)) throw new Error("Recipient missing in notification");
if (deliveries[result.target_chat_id] === null) deliveries[result.target_chat_id]=result.telegram_result_id;
const complete=Object.values(deliveries).every(id=>id !== null);
return [{json:{queue_id:row.id,item_id:row.item_id,
  deliveries_json:JSON.stringify(deliveries),status:complete ? "sent" : "pending",
  sent_at:complete ? (row.sent_at || new Date().toISOString()) : null,
  search_id:row.search_id,last_error:complete ? "" : String(row.last_error ?? "")}}];

