const row=$('Take notification').all(0,-1)[0].json;
const deliveries=parseDeliveries(row.deliveries_json);
const errors=[];let retryAfter=0;let sentAt=row.sent_at || null;
for(const item of $input.all()){
  const result=item.json;
  if(result.deliveries_json){const partial=parseDeliveries(result.deliveries_json);for(const id of Object.keys(deliveries))if(partial[id])deliveries[id]=partial[id];}
  if(result.recipient_error)errors.push(String(result.recipient_error));
  retryAfter=Math.max(retryAfter,Number(result.retry_after)||0);
  if(result.sent_at)sentAt=result.sent_at;
}
const complete=Object.values(deliveries).every(id=>id !== null);
const attempts=Number(row.attempts ?? 0)+(complete ? 0 : 1);
const delay=Math.max($('C Plan').first().json.interval_seconds,retryAfter);
return [{json:{queue_id:row.id,item_id:row.item_id,
  deliveries_json:JSON.stringify(deliveries),status:complete ? "sent" : attempts >= 3 ? "failed" : "pending",
  attempts,next_attempt_at:complete ? null : new Date(Date.now()+delay*1000).toISOString(),
  sent_at:complete ? (sentAt || new Date().toISOString()) : null,
  last_error:complete ? "" : (errors.join("; ") || "Not all deliveries confirmed").slice(0,1000),
  search_id:row.search_id}}];

